contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(string calldata description) public {
        // msg.sender (this contract) has not been granted admin rights, and C
        // provides no way to become one, so the call must revert.
        bool reverted;
        try c.newEmergencyOracle(description) { reverted = false; } catch { reverted = true; }
        assert(reverted);
    }
}
